\set ON_ERROR_STOP off
create temp table res(nome text, ok boolean); grant all on res to anon, authenticated;
create or replace function pg_temp.chk(n text, ok boolean) returns void language sql as $$ insert into res values (n, coalesce(ok,false)) $$;
create or replace function pg_temp.tenta(n text, sql text) returns void language plpgsql as $$ begin execute sql; insert into res values (n, false); exception when others then insert into res values (n, true); end $$;
grant execute on function pg_temp.chk(text,boolean), pg_temp.tenta(text,text) to anon, authenticated;
insert into auth.users (id,email) values ('00000000-0000-0000-0000-000000000001','admin@t.com'),('00000000-0000-0000-0000-000000000002','op@t.com'),('00000000-0000-0000-0000-000000000003','leit@t.com');
select pg_temp.chk('perfil: 1º usuário é admin', (select papel from cab_perfis where user_id='00000000-0000-0000-0000-000000000001')='admin');
select pg_temp.chk('perfil: demais entram como leitura', (select papel from cab_perfis where user_id='00000000-0000-0000-0000-000000000002')='leitura');
update cab_perfis set papel='operador' where user_id='00000000-0000-0000-0000-000000000002';
set role anon; select pg_temp.tenta('anon NÃO lê cab_cartas','select 1 from cab_cartas'); select pg_temp.tenta('anon NÃO gera número',$q$select cab_proximo_numero(2026)$q$); reset role;
set role authenticated; set request.jwt.claim.sub='00000000-0000-0000-0000-000000000002'; set request.jwt.claim.email='op@t.com';
select pg_temp.chk('numeração 1', cab_proximo_numero(2026)='CAB-2026-0001'); select pg_temp.chk('numeração 2', cab_proximo_numero(2026)='CAB-2026-0002'); select pg_temp.chk('ano novo reinicia', cab_proximo_numero(2027)='CAB-2027-0001');
insert into cab_cartas (numero,modo,tipo_conta,status,banco_nome,titular_nome,texto_final,hash_conteudo,codigo_verificacao) values ('CAB-2026-0001','manual','pj','emitida','Banco X','Fulano','texto','h123','ABCD123456');
select pg_temp.chk('operador cria carta', exists(select 1 from cab_cartas where numero='CAB-2026-0001'));
select pg_temp.tenta('número duplicado barrado',$q$insert into cab_cartas (numero,modo,tipo_conta,texto_final,hash_conteudo,codigo_verificacao) values ('CAB-2026-0001','manual','pj','t','h','ZZZ')$q$);
select pg_temp.tenta('texto emitido não muda',$q$update cab_cartas set texto_final='outro' where numero='CAB-2026-0001'$q$);
update cab_cartas set status='cancelada' where numero='CAB-2026-0001'; select pg_temp.chk('operador cancela carta', (select status from cab_cartas where numero='CAB-2026-0001')='cancelada');
delete from cab_cartas where numero='CAB-2026-0001'; select pg_temp.chk('operador NÃO apaga carta', exists(select 1 from cab_cartas where numero='CAB-2026-0001'));
update cab_contadores set ultimo_numero=0;
insert into cab_auditoria (carta_id,evento) select id,'emitida' from cab_cartas limit 1;
update cab_auditoria set evento='x'; delete from cab_auditoria;
insert into cab_empresas (razao_social) values ('Acme'); select pg_temp.chk('operador grava cadastro', exists(select 1 from cab_empresas));
select cab_log('teste'); select pg_temp.chk('log grava e admin-only lê', not exists(select 1 from cab_log));
reset role;
select pg_temp.chk('contador não editável direto', (select ultimo_numero from cab_contadores where ano=2026)=2);
select pg_temp.chk('auditoria imutável (update/delete)', exists(select 1 from cab_auditoria where evento='emitida') and not exists(select 1 from cab_auditoria where evento='x'));
set role authenticated; set request.jwt.claim.sub='00000000-0000-0000-0000-000000000003';
select pg_temp.chk('leitura enxerga cartas', exists(select 1 from cab_cartas)); insert into cab_empresas (razao_social) values ('Nao'); select pg_temp.chk('leitura NÃO grava', (select count(*) from cab_empresas)=1);
select pg_temp.tenta('leitura NÃO gera número',$q$select cab_proximo_numero(2026)$q$);
reset role; set role authenticated; set request.jwt.claim.sub='00000000-0000-0000-0000-000000000009';
select pg_temp.chk('sem perfil não lê', not exists(select 1 from cab_cartas)); reset role;
